divmod:
: divmod-loop
  (forall ρ; ρ q:Int^many r:Int^many b:Int^many -- ρ q:Int^many r:Int^many)
  locals { q r b } {
    r b prim <
    [
      q r
    ]
    [
      q 1 prim +
      r b prim -
      b
      divmod-loop
    ]
    if
  };

: main
  (forall ρ; ρ a:Int^many b:Int^many -- ρ q:Int^many r:Int^many)
  locals { a b } {
    0 a b divmod-loop
  };

isqrt:
: isqrt-loop
  (forall ρ; ρ r:Int^many n:Int^many -- ρ r:Int^many)
  locals { r n } {
    r 1 prim +
    dup dup prim *
    n prim <
    [
      n isqrt-loop
    ]
    [
      drop r
    ]
    if
  };

: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  locals { n } {
    0 n isqrt-loop
  };

is-prime:
: is-prime-check
  (forall ρ; ρ c:Int^many l:Int^many n:Int^many -- ρ r:Bool^many)
  locals { c l n } {
    c l prim <
    [
      1
    ]
    [
      n c prim -
      0 prim =
      [
        0
      ]
      [
        c 1 prim +
        l
        n
        is-prime-check
      ]
      if
    ]
    if
  };

: main
  (forall ρ; ρ n:Int^many -- ρ r:Bool^many)
  locals { n } {
    n 2 prim <
    [
      0
    ]
    [
      n 2 prim =
      [
        1
      ]
      [
        n 2 prim -
        dup 1 prim +
        n
        is-prime-check
      ]
      if
    ]
    if
  };

digit-sum:
: digit-sum-loop
  (forall ρ; ρ s:Int^many n:Int^many -- ρ r:Int^many)
  locals { s n } {
    n 0 prim =
    [
      s
    ]
    [
      n 10 prim -
      0 prim =
      [
        s n prim +
      ]
      [
        s n prim - prim +
        n 10 prim -
        digit-sum-loop
      ]
      if
    ]
    if
  };

: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  locals { n } {
    0 n digit-sum-loop
  };

lcm:
: gcd
  (forall ρ; ρ a:Int^many b:Int^many -- ρ r:Int^many)
  locals { a b } {
    b 0 prim =
    [
      a
    ]
    [
      a b prim =
      [
        b
      ]
      [
        b a b prim - gcd
      ]
      if
    ]
    if
  };

: main
  (forall ρ; ρ a:Int^many b:Int^many -- ρ r:Int^many)
  locals { a b } {
    a b gcd
    locals { g } {
      a b prim *
      g prim -
      0 prim =
      [
        a b prim *
      ]
      [
        a b prim *
      ]
      if
    }
  };
